using Microsoft.EntityFrameworkCore;
using pcms.Application.Inventory;
using pcms.Domain.Entities;
using pcms.Domain.Enums;
using pcms.Infrastructure.Persistence;
namespace pcms.Infrastructure.Services;
public class ManufacturedUrnProductionService(AppDbContext db) : IManufacturedUrnProductionService
{
 public async Task<ProductionDto> CreateAsync(ProductionInput input,Guid? userId){if(input.QuantityProduced<=0||input.Usages.Count==0)throw new ArgumentException("La producción requiere cantidad y materiales.");await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var bom=await db.UrnBillOfMaterials.Include(x=>x.Urn).Include(x=>x.Items).ThenInclude(x=>x.SupplyItem).FirstOrDefaultAsync(x=>x.Id==input.UrnBillOfMaterialsId&&x.UrnId==input.UrnId);if(bom is null)throw new ArgumentException("La BOM no existe.");var mapping=await db.UrnSupplyItems.Include(x=>x.SupplyItem).FirstOrDefaultAsync(x=>x.UrnId==input.UrnId&&x.IsActive);if(mapping is null||!mapping.SupplyItem.IsActive||!mapping.SupplyItem.TrackInventory||!Piece(mapping.SupplyItem.UnitOfMeasure))throw new InvalidOperationException("La urna requiere un insumo terminado activo y compatible.");if(await db.ManufacturedUrnProductions.AnyAsync(x=>x.FinishedGoodsReceiptMovementId!=null&&x.Id==Guid.Empty))throw new InvalidOperationException("Producción duplicada.");var usages=input.Usages.ToDictionary(x=>x.SupplyItemId);if(usages.Count!=bom.Items.Count||bom.Items.Any(x=>!usages.ContainsKey(x.SupplyItemId)))throw new ArgumentException("Debe registrar todos los materiales de la BOM.");var p=new ManufacturedUrnProduction{Id=Guid.NewGuid(),UrnId=input.UrnId,UrnBillOfMaterialsId=bom.Id,QuantityProduced=decimal.Round(input.QuantityProduced,3),ProducedAt=input.ProducedAt??DateTime.UtcNow,Notes=input.Notes,RecordedByUserId=userId,CreatedAt=DateTime.UtcNow};foreach(var b in bom.Items){var u=usages[b.SupplyItemId];if(u.ActualQuantity<=0)throw new ArgumentException("Las cantidades utilizadas deben ser mayores que cero.");var item=await db.SupplyItems.FirstOrDefaultAsync(x=>x.Id==b.SupplyItemId&&x.IsActive&&x.TrackInventory)??throw new InvalidOperationException("Un material no controla inventario.");var rows=await db.SupplyInventoryMovements.Where(x=>x.SupplyItemId==item.Id).Select(x=>new{x.MovementType,x.Quantity}).ToListAsync();if(rows.Sum(x=>Sign(x.MovementType)*x.Quantity)<u.ActualQuantity)throw new InvalidOperationException($"Inventario insuficiente para {item.Name}.");var source=await db.SupplierSupplyItems.AsNoTracking().Where(x=>x.SupplyItemId==item.Id&&x.IsActive&&x.IsPreferred&&x.InventoryUnitsPerPurchaseUnit>0).SingleOrDefaultAsync();decimal? cost=source is null?null:source.CurrentUnitCost/source.InventoryUnitsPerPurchaseUnit;var move=new SupplyInventoryMovement{Id=Guid.NewGuid(),SupplyItemId=item.Id,MovementType=SupplyInventoryMovementType.ManufacturingConsumption,Quantity=decimal.Round(u.ActualQuantity,3),UnitOfMeasure=b.UnitOfMeasure,OccurredAt=p.ProducedAt,Reference=p.Id.ToString(),Notes="Consumo de producción",RecordedByUserId=userId,CreatedAt=DateTime.UtcNow};db.Add(move);p.MaterialUsages.Add(new ManufacturingMaterialUsage{Id=Guid.NewGuid(),ProductionId=p.Id,SupplyItemId=item.Id,SupplyItemNameSnapshot=item.Name,ExpectedQuantity=b.RequiredQuantity,ActualQuantity=decimal.Round(u.ActualQuantity,3),WasteQuantity=u.WasteQuantity is null?null:decimal.Round(u.WasteQuantity.Value,3),UnitOfMeasure=b.UnitOfMeasure,CostPerUnitSnapshot=cost,TotalMaterialCostSnapshot=cost is null?null:decimal.Round(cost.Value*u.ActualQuantity,4),InventoryMovementId=move.Id,CreatedAt=DateTime.UtcNow});}var receipt=new SupplyInventoryMovement{Id=Guid.NewGuid(),SupplyItemId=mapping.SupplyItemId,MovementType=SupplyInventoryMovementType.ManufacturingReceipt,Quantity=p.QuantityProduced,UnitOfMeasure=mapping.SupplyItem.UnitOfMeasure,OccurredAt=p.ProducedAt,Reference=p.Id.ToString(),Notes="Entrada de urna fabricada",RecordedByUserId=userId,CreatedAt=DateTime.UtcNow};db.Add(receipt);p.FinishedGoodsReceiptMovementId=receipt.Id;db.Add(p);await db.SaveChangesAsync();await tx.CommitAsync();return (await GetAllAsync(p.UrnId,false)).First(x=>x.Id==p.Id);}
 public async Task<IEnumerable<ProductionDto>> GetAllAsync(Guid? urnId,bool includeCost){var q=db.ManufacturedUrnProductions.AsNoTracking().Include(x=>x.Urn).Include(x=>x.UrnBillOfMaterials).Include(x=>x.MaterialUsages).ThenInclude(x=>x.SupplyItem).AsQueryable();if(urnId.HasValue)q=q.Where(x=>x.UrnId==urnId);return (await q.OrderByDescending(x=>x.ProducedAt).ToListAsync()).Select(x=>Map(x,includeCost));}
 static ProductionDto Map(ManufacturedUrnProduction x,bool cost){var us=x.MaterialUsages.Select(u=>new ProductionUsageDto(u.Id,u.SupplyItemId,u.SupplyItemNameSnapshot,u.ExpectedQuantity,u.ActualQuantity,u.WasteQuantity,u.UnitOfMeasure,cost?u.CostPerUnitSnapshot:null,cost?u.TotalMaterialCostSnapshot:null)).ToList();var complete=us.All(u=>u.CostPerUnitSnapshot.HasValue);return new(x.Id,x.UrnId,x.Urn.Name,x.UrnBillOfMaterialsId,x.UrnBillOfMaterials.Version,x.QuantityProduced,x.ProducedAt,x.Notes,us,cost&&complete?us.Sum(u=>u.TotalMaterialCostSnapshot!.Value):null,complete);}
 static bool Piece(string u)=>new[]{"pieza","pza","unidad","units"}.Contains(u.ToLowerInvariant()); static int Sign(SupplyInventoryMovementType t)=>t is SupplyInventoryMovementType.ManualAdjustmentDecrease or SupplyInventoryMovementType.Consumption or SupplyInventoryMovementType.Waste or SupplyInventoryMovementType.PurchaseReturn or SupplyInventoryMovementType.ManufacturingConsumption?-1:1;
}
